1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Result = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	const CURSE_SURCHARGE_RATE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT_RATE = 0.2;
33	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
34	
35	const BASE_PREMIUMS: Record<string, number> = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	  potion: 40,
40	  rune: 25,
41	  moonstone: 25,
42	};
43	
44	const BLOCK_SIZE = 3;
45	const BLOCK_PREMIUM = 60;
46	
47	/** Items that share the same `type`, and so are priced together. */
48	type AlikeItems = Item[];
49	
50	const groupAlikeItems = (items: Item[]): AlikeItems[] => {
51	  const byType = new Map<string, AlikeItems>();
52	  items.forEach((item) => byType.set(item.type, [...(byType.get(item.type) ?? []), item]));
53	  return [...byType.values()];
54	};
55	
56	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
57	
58	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
59	
60	const alikeItemsBasePremium = (alikeItems: AlikeItems): number =>
61	  formsBlock(alikeItems)
62	    ? BLOCK_PREMIUM
63	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
64	
65	const totalBasePremium = (items: Item[]): number =>
66	  groupAlikeItems(items).reduce((total, alikeItems) => total + alikeItemsBasePremium(alikeItems), 0);
67	
68	const isCursed = (item: Item): boolean => item.cursed === true;
69	
70	const isHighlyEnchanted = (item: Item): boolean =>
71	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
72	
73	/**
74	 * An additive rate rule: contributes `rate` × some base premium, but only to
75	 * subjects the rule `applies` to. Every rule is an independent additive term —
76	 * nothing compounds onto a running total — so a discount is simply a negative
77	 * `rate` rather than a subtraction applied at some point in a sequence.
78	 */
79	type RateRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
80	
81	/**
82	 * The combined rate of every rule that applies to `subject`. Callers multiply
83	 * this by the relevant base premium once, which keeps each rule additive.
84	 */
85	const applicableRates = <Subject>(rules: RateRule<Subject>[], subject: Subject): number =>
86	  rules.filter(({ applies }) => applies(subject)).reduce((total, { rate }) => total + rate, 0);
87	
88	/** Charged on each cursed/enchanted item's own base premium, not the policy's. */
89	const ITEM_SURCHARGES: RateRule<Item>[] = [
90	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
91	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
92	];
93	
94	const itemSurchargeTotal = (item: Item): number =>
95	  itemBasePremium(item) * applicableRates(ITEM_SURCHARGES, item);
96	
97	const totalItemSurcharges = (items: Item[]): number =>
98	  items.reduce((total, item) => total + itemSurchargeTotal(item), 0);
99	
100	/** Everything a policy-wide rule may look at when deciding whether it applies. */
101	type Policy = { customer: Customer; priorContracts: number };
102	
103	const isLoyalCustomer = ({ customer }: Policy): boolean =>
104	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
105	
106	const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;
107	
108	/**
109	 * Charged once per quote on the policy's base premium.
110	 *
111	 * The unconditional first-insurance surcharge is deliberately not in this table:
112	 * see `FIRST_INSURANCE_SURCHARGE_RATE` at the quote site.
113	 */
114	const POLICY_ADJUSTMENTS: RateRule<Policy>[] = [
115	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
116	  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
117	];
118	
119	const totalPolicyAdjustments = (policyBasePremium: number, policy: Policy): number =>
120	  policyBasePremium * applicableRates(POLICY_ADJUSTMENTS, policy);
121	
122	const quotePremium = (items: Item[], policy: Policy): number => {
123	  const policyBasePremium = totalBasePremium(items);
124	  // The first-insurance surcharge has no condition to test: the MHPCO treats
125	  // every item in a quote as newly insured, so it is charged on every quote,
126	  // including a long-standing customer's follow-up contract. That makes it a
127	  // fixed rate on the base — like PROCESSING_FEE is a fixed addend — rather
128	  // than a rule belonging in POLICY_ADJUSTMENTS.
129	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
130	  // Every term is added to the base, never multiplied onto a running total. The
131	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
132	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
133	  return Math.ceil(
134	    policyBasePremium +
135	      totalItemSurcharges(items) +
136	      firstInsuranceSurcharge +
137	      totalPolicyAdjustments(policyBasePremium, policy) +
138	      PROCESSING_FEE,
139	  );
140	};
141	
142	const isQuote = (step: Step): boolean => step.op === "quote";
143	
144	/**
145	 * A contract is created by each quote, so the number the customer already held
146	 * when `stepIndex` is reached is just the number of quotes before it. Claims are
147	 * not contracts and so do not count.
148	 */
149	const priorContractsAt = (steps: Step[], stepIndex: number): number =>
150	  steps.slice(0, stepIndex).filter(isQuote).length;
151	
152	export const runScenario = (scenario: Scenario): Result[] =>
153	  scenario.steps.map((step, stepIndex) => {
154	    if (step.op === "quote") {
155	      const policy = {
156	        customer: scenario.customer,
157	        priorContracts: priorContractsAt(scenario.steps, stepIndex),
158	      };
159	      return { premium: quotePremium(step.items, policy) };
160	    }
161	    throw new Error(`Unsupported step: ${step.op}`);
162	  });
